def verifier(assign):
    import math

    # Extract parameters
    base_term = assign.get('base_term')
    A = assign.get('A_coef')
    B = assign.get('B_coef')
    G = assign.get('G_coef')
    D = assign.get('D_coef')
    r = assign.get('r_param')
    lam_num = assign.get('lam_num')
    lam_den = assign.get('lam_den')
    mu = assign.get('mu')
    p = assign.get('p')
    q = assign.get('q')
    N = assign.get('N')

    # Basic validation of presence
    if None in [base_term, A, B, G, D, r, lam_num, lam_den, mu, p, q, N]:
        # Missing parameters
        return (False, None)

    # Helper functions
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return abs(a)
    def real_cuberoot(z):
        # Real cube root handling negative values
        if z >= 0:
            return z ** (1.0/3.0)
        else:
            return -((-z) ** (1.0/3.0))

    # Reconstruct s, t, x, y
    s = p / q
    if not (0 < s < 1):
        return (False, None)
    x = (1 - s*s) / 2.0
    # From construction: t = (r + s)/N
    t = (r + s) / N
    if not (0 < t < 1):
        return (False, None)
    y = (1 - t*t) / 2.0
    if not (0 < x < 0.5 and 0 < y < 0.5):
        return (False, None)

    # Check the rational-square constraint numerically
    left_sq = mu * (1 + 5*(s*s) - 2*s) / 2.0
    right_sq = ((r + s) / (t)) ** 2
    if abs(left_sq - right_sq) > 1e-7:
        # Constraint failed
        return (False, None)

    # Check the main identity numerically
    lam = lam_num / lam_den
    # Cardano A_term
    Aterm = (r**3 + 3*r*lam*(x**2)) / 2.0
    rad = math.sqrt((Aterm)**2 + (lam**3) * (x**6))
    c1 = real_cuberoot(Aterm + rad)
    c2 = real_cuberoot(Aterm - rad)
    frac = (A + B * s) / (G + D * s)
    LHS = base_term + math.sqrt(1 - 2*y)
    RHS = y + frac + c1 + c2
    if abs(LHS - RHS) > 1e-7:
        # Identity failed
        return (False, None)

    # Compute minimal k such that kx and ky are integers
    # x = (q^2 - p^2)/(2 q^2)
    x_num = q*q - p*p
    x_den = 2*q*q
    gx = gcd(x_num, x_den)
    x_den_red = x_den // gx
    # y = (t_den^2 - t_num^2)/(2 t_den^2), t_den = N q, t_num = r q + p
    t_den = N * q
    t_num = r*q + p
    y_num = t_den*t_den - t_num*t_num
    y_den = 2 * t_den * t_den
    gy = gcd(y_num, y_den)
    y_den_red = y_den // gy
    # lcm
    def lcm(a, b):
        return a // gcd(a, b) * b
    k_min = lcm(x_den_red, y_den_red)

    # Additional difficulty enforcement: ensure k is large enough
    if k_min < 5000:
        return (False, None)

    answer = f"### The final answer is: \\boxed{{{k_min}}}"
    return (True, answer)
